public class Main {

    static void procesar(Object obj) {
        String resultado = switch (obj) {
            case String s -> "Text of " + s.length() + " characters";
            case Integer i -> (i % 2 == 0) ? "Even integer: " + i : "Odd integer: " + i;
            case Double d -> String.format("Decimal: %.2f", d);
            default -> "Not supported";
        };
        System.out.println(resultado);
    }

    public static void main(String[] args) {
        procesar("Java 21");
        procesar(10);
        procesar(7);
        procesar(2.71828);
        procesar(true);
    }
}

