interface Forma permits Ciculo, Rectangulo, Triangulo {
    double area();
}

record Ciculo(double radio) implements Forma {
    @Override
    public double area() { return Math.PI * radio * radio; }
}

record Rectangulo(double base, double altura) implements Forma {
    @Override
    public double area() { return base * altura; }
}

record Triangulo(double base, double altura) implements Forma {
    @Override
    public double area() { return (base * altura) / 2; }
}

public class Main {

    static double calcularArea(Forma forma) {
        return switch (forma) {
            case Ciculo c -> c.area();
            case Rectangulo r -> r.area();
            case Triangulo t -> t.area();
        };
    }

    public static void main(String[] args) {
        Forma[] formas = {
            new Ciculo(5),
            new Rectangulo(4, 6),
            new Triangulo(3, 8)
        };

        for (Forma f : formas) {
            System.out.println(f + " -> Area: " + String.format("%.2f", calcularArea(f)));
        }
    }
}
